// Rate limiter with sliding window
class RateLimiter {
  constructor(windowMs, maxAttempts) {
    this.windowMs = windowMs;
    this.maxAttempts = maxAttempts;
    this.attempts = new Map();
    // Cleanup expired entries every minute
    setInterval(() => this.cleanup(), 60000);
  }

  cleanup() {
    const now = Date.now();
    for (const [key, records] of this.attempts) {
      const valid = records.filter(ts => now - ts < this.windowMs);
      if (valid.length === 0) this.attempts.delete(key);
      else this.attempts.set(key, valid);
    }
  }

  isRateLimited(key) {
    const now = Date.now();
    const records = this.attempts.get(key) || [];
    const windowRecords = records.filter(ts => now - ts < this.windowMs);
    this.attempts.set(key, windowRecords);
    return windowRecords.length >= this.maxAttempts;
  }

  recordAttempt(key) {
    const now = Date.now();
    const records = this.attempts.get(key) || [];
    records.push(now);
    this.attempts.set(key, records);
  }
}

const loginLimiter = new RateLimiter(900000, 5); // 15 min window, 5 attempts

// TOTP implementation
function generateTOTP(secret, timeStep = 30) {
  const time = Math.floor(Date.now() / 1000 / timeStep);
  const buffer = Buffer.alloc(8);
  buffer.writeUInt32BE(0, 0);
  buffer.writeUInt32BE(time, 4);

  const decodedSecret = base32Decode(secret);
  const hmac = crypto.createHmac('sha1', decodedSecret).update(buffer).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const code = ((hmac[offset] & 0x7f) << 24 |
    (hmac[offset + 1] & 0xff) << 16 |
    (hmac[offset + 2] & 0xff) << 8 |
    (hmac[offset + 3] & 0xff)) % 1000000;
  return code.toString().padStart(6, '0');
}

function verifyTOTP(secret, token, window = 1) {
  if (typeof token !== 'string' || !/^\d{6}$/.test(token)) return false;
  for (let i = -window; i <= window; i++) {
    const time = Math.floor(Date.now() / 1000 / 30) + i;
    const buffer = Buffer.alloc(8);
    buffer.writeUInt32BE(0, 0);
    buffer.writeUInt32BE(time, 4);
    const decodedSecret = base32Decode(secret);
    const hmac = crypto.createHmac('sha1', decodedSecret).update(buffer).digest();
    const offset = hmac[hmac.length - 1] & 0x0f;
    const code = ((hmac[offset] & 0x7f) << 24 |
      (hmac[offset + 1] & 0xff) << 16 |
      (hmac[offset + 2] & 0xff) << 8 |
      (hmac[offset + 3] & 0xff)) % 1000000;
    const expected = code.toString().padStart(6, '0');
    if (crypto.timingSafeEqual(Buffer.from(token), Buffer.from(expected))) {
      return true;
    }
  }
  return false;
}

function base32Decode(input) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const char of input.toUpperCase()) {
    const val = alphabet.indexOf(char);
    if (val === -1) continue;
    bits += val.toString(2).padStart(5, '0');
  }
  const bytes = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.slice(i, i + 8), 2));
  }
  return Buffer.from(bytes);
}

// Session management
const sessions = new Map();

function createSession(username, role) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const session = {
    id: sessionId,
    username,
    role,
    createdAt: Date.now(),
    expiresAt: Date.now() + 3600000 // 1 hour
  };
  sessions.set(sessionId, session);
  return sessionId;
}

function validateSession(sessionId) {
  if (typeof sessionId !== 'string' || sessionId.length !== 64) return null;
  const session = sessions.get(sessionId);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    return null;
  }
  return session;
}

// Username normalization applied consistently at all points
function normalizeUsername(input) {
  if (typeof input !== 'string') return '';
  // Normalize Unicode to canonical form for consistent comparison
  return input.normalize('NFKC').toLowerCase().trim();
}

// Login endpoint with MFA
app.post('/auth/login', async (req, res) => {
  const { username, password, totpToken } = req.body;

  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid request' });
  }

  if (typeof totpToken !== 'string') {
    return res.status(400).json({ error: 'MFA token required' });
  }

  // Normalize username FIRST, then use normalized form for ALL operations
  const normalizedUsername = normalizeUsername(username);

  // Rate limit check uses the normalized username
  const rateLimitKey = `login:${normalizedUsername}`;

  if (loginLimiter.isRateLimited(rateLimitKey)) {
    return res.status(429).json({ error: 'Too many attempts. Try again later.' });
  }

  // Record attempt before checking credentials
  loginLimiter.recordAttempt(rateLimitKey);

  const user = users.get(normalizedUsername);

  if (!user) {
    // Constant-time dummy operation to prevent user enumeration
    await argon2.verify(
      '$argon2id$v=19$m=65536,t=3,p=4$c29tZXNhbHQ$RdescudvJCsgt3ub+b+dWRWJTmaaJObG',
      password
    ).catch(() => {});
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  try {
    const validPassword = await argon2.verify(user.passwordHash, password);
    if (!validPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (err) {
    return res.status(500).json({ error: 'Authentication error' });
  }

  // Verify TOTP
  if (!verifyTOTP(user.mfaSecret, totpToken)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const sessionId = createSession(normalizedUsername, user.role);
  res.cookie('session', sessionId, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    maxAge: 3600000
  });
  res.json({ message: 'Login successful', role: user.role });
});

// Auth middleware
function requireAuth(requiredRole) {
  return (req, res, next) => {
    const sessionId = req.cookies?.session;
    const session = validateSession(sessionId);
    if (!session) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    if (requiredRole && session.role !== requiredRole) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    req.session = session;
    next();
  };
}

// Protected endpoints
app.get('/api/data', requireAuth(), (req, res) => {
